const root = process.env.ZODY_CUA_PLUGIN_ROOT ?? process.env.ZCODE_PLUGIN_ROOT ?? process.env.CLAUDE_PLUGIN_ROOT;
const { join } = await import('node:path');
const { pathToFileURL } = await import('node:url');
const { setupComputerUseRuntime } = await import(pathToFileURL(join(root, 'scripts', 'computer-use-client.mjs')).href);
await setupComputerUseRuntime({ globals: globalThis });
const { readFile } = await import('node:fs/promises');
const f = JSON.parse(await readFile('{{e2eRuntimeRoot}}/cua-r1/manifest.json', 'utf8'));
const ref = { pid: f.pid, window_id: f.targetWindow };
const result = await agent.computerUse.computer.get_app_state({app_ref:ref,include_screenshot:true});
const blocks = Array.isArray(result?.content) ? result.content : [];
const images = blocks.filter(b => b.type === 'image' && b.mimeType === 'image/png' && typeof b.data === 'string' && b.data.length > 0);
const text = typeof result === 'string' ? result : JSON.stringify(blocks.filter(b => b.type === 'text'));
const parsed = typeof result === 'object' && !Array.isArray(result?.content) ? result : (() => { try { return JSON.parse(text); } catch { return null; } })();
if (images.length || parsed?.code !== 'permission_denied' || text.includes(f.targetMarker) || text.includes(f.siblingMarker)) throw new Error('SCREENSHOT_DENY_FAILED');
nodeRepl.write('CUA_SHOT_DENY_OK');

